# ============================================================================\n# Project Nyra - Orchestrator Setup Script\n# ============================================================================\n# Purpose: Complete bootstrap for Orchestrator PC (Minisforum UH680)\n# Installs: Docker, Tailscale, starts all orchestrator services\n# Prerequisites: Windows 11, Administrator access, Internet connection\n# ============================================================================\n\nparam(\n    [string]$BootstrapPath = \"$PSScriptRoot\\..\\..\",\n    [switch]$SkipDockerInstall = $false,\n    [switch]$SkipTailscale = $false\n)\n\n$ErrorActionPreference = \"Stop\"\n\nfunction Write-Log {\n    param([string]$Message, [string]$Level = \"INFO\")\n    $timestamp = Get-Date -Format \"yyyy-MM-dd HH:mm:ss\"\n    $color = @{ \"ERROR\" = \"Red\"; \"WARN\" = \"Yellow\"; \"SUCCESS\" = \"Green\" }[[string]$Level] ?? \"Cyan\"\n    Write-Host \"[$timestamp] [$Level] $Message\" -ForegroundColor $color\n}\n\nfunction Test-AdminPrivileges {\n    $isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]\"Administrator\")\n    if (-not $isAdmin) {\n        Write-Log \"This script requires Administrator privileges. Please run PowerShell as Administrator.\" \"ERROR\"\n        exit 1\n    }\n}\n\nfunction Install-Docker {\n    if ($SkipDockerInstall) {\n        Write-Log \"Skipping Docker installation (--SkipDockerInstall flag set)\"\n        return\n    }\n    \n    Write-Log \"Checking Docker Desktop installation...\"\n    \n    try {\n        $dockerVersion = docker --version 2>&1\n        Write-Log \"Docker already installed: $dockerVersion\" \"SUCCESS\"\n        return\n    }\n    catch {\n        Write-Log \"Docker not found. Installing Docker Desktop...\"\n    }\n    \n    # Download and install Docker Desktop\n    $dockerUrl = \"https://desktop.docker.com/win/stable/Docker%20Desktop%20Installer.exe\"\n    $installerPath = \"$env:TEMP\\DockerDesktopInstaller.exe\"\n    \n    Write-Log \"Downloading Docker Desktop...\"\n    Invoke-WebRequest -Uri $dockerUrl -OutFile $installerPath -TimeoutSec 300\n    \n    Write-Log \"Installing Docker Desktop (this may take several minutes)...\"\n    & $installerPath install --quiet --accept-license\n    \n    Write-Log \"Docker installation complete. You may need to restart Windows.\" \"SUCCESS\"\n    Write-Log \"After restart, rerun this script to continue.\"\n}\n\nfunction Install-Tailscale {\n    if ($SkipTailscale) {\n        Write-Log \"Skipping Tailscale installation (--SkipTailscale flag set)\"\n        return\n    }\n    \n    Write-Log \"Checking Tailscale installation...\"\n    \n    try {\n        $tailscaleVersion = tailscale version 2>&1\n        Write-Log \"Tailscale already installed\" \"SUCCESS\"\n    }\n    catch {\n        Write-Log \"Installing Tailscale...\"\n        # Use Tailscale installer\n        $tailscaleUrl = \"https://pkgs.tailscale.com/windows/tailscale-setup-latest.exe\"\n        $installerPath = \"$env:TEMP\\tailscale-installer.exe\"\n        Invoke-WebRequest -Uri $tailscaleUrl -OutFile $installerPath\n        & $installerPath\n        Write-Log \"Tailscale installed\" \"SUCCESS\"\n    }\n}\n\nfunction Setup-TailscaleVPN {\n    Write-Log \"Setting up Tailscale VPN...\"\n    \n    # Get auth key from environment or prompt\n    $authKey = $env:TAILSCALE_AUTHKEY\n    if (-not $authKey) {\n        Write-Log \"TAILSCALE_AUTHKEY environment variable not set.\"\n        Write-Log \"Get an auth key from https://tailscale.com/admin/settings/keys\"\n        $authKey = Read-Host \"Enter Tailscale auth key\"\n    }\n    \n    if ($authKey) {\n        Write-Log \"Connecting to Tailscale...\"\n        & tailscale up --auth-key=$authKey --hostname=orchestrator-mini --advertise-exit-node --force-reauth\n        Write-Log \"Tailscale connected\" \"SUCCESS\"\n    }\n    else {\n        Write-Log \"Skipping Tailscale connection (no auth key provided)\" \"WARN\"\n    }\n}\n\nfunction Start-OrchestratorServices {\n    Write-Log \"Starting Orchestrator services...\"\n    \n    $composePath = Join-Path $BootstrapPath \"docker-composes\\orchestrator-complete.yml\"\n    \n    if (!(Test-Path $composePath)) {\n        Write-Log \"Docker compose file not found: $composePath\" \"ERROR\"\n        exit 1\n    }\n    \n    # Load environment variables\n    $envPath = Join-Path $BootstrapPath \"configs\\env-templates\\.env.orchestrator\"\n    if (Test-Path $envPath) {\n        Write-Log \"Loading environment from: $envPath\"\n        # In production, load from Infisical\n    }\n    \n    Write-Log \"Starting docker-compose services...\"\n    Push-Location (Split-Path $composePath)\n    docker-compose -f (Split-Path $composePath -Leaf) up -d\n    Pop-Location\n    \n    Write-Log \"Waiting for services to be healthy...\"\n    Start-Sleep -Seconds 30\n    \n    Write-Log \"Checking service health...\"\n    $services = @(\"nyra-metamcp\", \"nyra-archon\", \"nyra-infisical\", \"nyra-gitea\")\n    foreach ($service in $services) {\n        $status = docker ps --filter \"name=$service\" --format \"table {{.Names}}\\t{{.Status}}\"\n        if ($status) {\n            Write-Log \"  $service: Running\" \"SUCCESS\"\n        }\n        else {\n            Write-Log \"  $service: NOT FOUND\" \"WARN\"\n        }\n    }\n}\n\nfunction Initialize-Services {\n    Write-Log \"Initializing services...\"\n    \n    # Gitea initialization\n    Write-Log \"Initializing Gitea...\"\n    try {\n        docker exec nyra-gitea gitea admin create-user --username=admin --password=admin --admin --email=admin@ratehunter.net\n        Write-Log \"Gitea admin user created\" \"SUCCESS\"\n    }\n    catch {\n        Write-Log \"Gitea initialization: $_\" \"WARN\"\n    }\n    \n    # Verify MetaMCP is responding\n    Write-Log \"Verifying MetaMCP health...\"\n    try {\n        $health = Invoke-WebRequest -Uri \"http://localhost:12008/health\" -TimeoutSec 5\n        if ($health.StatusCode -eq 200) {\n            Write-Log \"MetaMCP is healthy\" \"SUCCESS\"\n        }\n    }\n    catch {\n        Write-Log \"MetaMCP health check failed: $_\" \"WARN\"\n    }\n}\n\nfunction Display-Summary {\n    Write-Log \"========================================\" \n    Write-Log \"Orchestrator Setup Complete!\" \"SUCCESS\"\n    Write-Log \"========================================\"\n    Write-Log \"\\nServices are running at:\"\n    Write-Log \"  MetaMCP:     http://localhost:12008\"\n    Write-Log \"  Archon API:  http://localhost:4000\"\n    Write-Log \"  Infisical:   http://localhost:8080\"\n    Write-Log \"  Gitea:       http://localhost:3001\"\n    Write-Log \"  Grafana:     http://localhost:3000\"\n    Write-Log \"\\nTailscale Status:\"\n    & tailscale status\n    Write-Log \"\\nNext Steps:\"\n    Write-Log \"  1. Access Grafana at http://localhost:3000\"\n    Write-Log \"  2. Initialize Infisical secrets\"\n    Write-Log \"  3. Setup Cloudflare tunnel\"\n    Write-Log \"  4. Bootstrap worker PCs\"\n    Write-Log \"========================================\"\n}\n\n# Main execution\ntry {\n    Write-Log \"========================================\"\n    Write-Log \"Project Nyra - Orchestrator Bootstrap\"\n    Write-Log \"========================================\"\n    \n    Test-AdminPrivileges\n    \n    Write-Log \"Bootstrap path: $BootstrapPath\"\n    \n    Install-Docker\n    Install-Tailscale\n    Setup-TailscaleVPN\n    Start-OrchestratorServices\n    Initialize-Services\n    Display-Summary\n    \n    Write-Log \"Orchestrator bootstrap completed successfully!\" \"SUCCESS\"\n}\ncatch {\n    Write-Log \"Error during orchestrator setup: $_\" \"ERROR\"\n    Write-Log \"Stack trace: $($_.ScriptStackTrace)\" \"ERROR\"\n    exit 1\n}\n"